// Comando de lectura Mitsubishi FX para M0..M7
// Formato: <ENQ> (0x05) o lectura de bloque de bits
// Para inicialización y sondeo continuo
const buf = Buffer.from([0x02, 0x30, 0x30, 0x38, 0x30, 0x30, 0x32, 0x03, 0x36, 0x41]);
msg.payload = buf;
return msg;

const raw = msg.payload;
if (!raw || raw.length === 0) return null;

// Buffer / Array de bytes recibidos
let bytes = Array.isArray(raw) ? raw : Buffer.from(raw);

// Estado previo guardado en contexto de flujo
let prev = flow.get('seeku_button_state') || { m0: false, m1: false, m2: false };

// Decodificación de estado de bits
let m0 = false; // Bomba Principal
let m1 = false; // Dosificador Sulfato
let m2 = false; // Dosificador Cloro

if (bytes.length >= 1) {
    const b = bytes[0];
    m0 = (b & 0x01) !== 0;
    m1 = (b & 0x02) !== 0;
    m2 = (b & 0x04) !== 0;
}

flow.set('seeku_button_state', { m0, m1, m2 });

// Detección de flancos ascendentes (Rising Edge)
let commandsToSend = [];

if (m0 && !prev.m0) {
    commandsToSend.push({ target: 'bomba_principal', command: 'start', source: 'SEEKU_HMI_M0' });
}
if (m1 && !prev.m1) {
    commandsToSend.push({ target: 'dosificador_sulfato', command: 'start', source: 'SEEKU_HMI_M1' });
}
if (m2 && !prev.m2) {
    commandsToSend.push({ target: 'dosificador_cloro', command: 'start', source: 'SEEKU_HMI_M2' });
}

if (commandsToSend.length > 0) {
    node.warn(`[SEEKU BOTÓN PULSADO] Comandos: ${JSON.stringify(commandsToSend)}`);
    return [commandsToSend.map(c => ({ payload: c }))];
}

return null;
